import React, { useEffect, useState } from 'react';
import { fetchForecast } from '../api/api';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Loader2, AlertCircle, TrendingUp, TrendingDown, Wallet, LineChart } from 'lucide-react';

/**
 * FORECASTING COMPONENT
 * Fetches time-series predictions generated by the Python backend (Prophet AI) 
 * and visualizes future spending/income trends using Recharts Area charts.
 */
const Forecasting = ({ userId, days = 30, bankFilter = 'All', categoryFilter = 'All', typeFilter = 'Expenses' }) => {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);

  // Helper function to format the future date range for the UI badge
  const getDateDisplay = () => {
    const today = new Date();
    const future = new Date();
    future.setDate(today.getDate() + parseInt(days));
    return `${today.toLocaleDateString()} - ${future.toLocaleDateString()}`;
  };

  /**
   * EFFECT: FETCH FORECAST DATA
   * Triggers whenever filter props change. Uses a timeout (debounce) to prevent 
   * spamming the backend API while the user is rapidly changing dropdowns.
   */
  useEffect(() => {
    const loadForecast = async () => {
      setLoading(true);
      const result = await fetchForecast(userId, days, categoryFilter, bankFilter, typeFilter);
      setData(result);
      setLoading(false);
    };
    const timeoutId = setTimeout(() => loadForecast(), 500);
    return () => clearTimeout(timeoutId);
  }, [days, bankFilter, categoryFilter, userId, typeFilter]); 

  // --- TREND & COLOR LOGIC ---
  const isIncreasing = data?.trend === 'increasing';
  const neonGreen = '#00c48c';
  const neonRed = '#eb3b5a';

  // Determine chart color based on Context:
  // For Income: Increasing is Good (Green), Decreasing is Bad (Red).
  // For Expenses: Increasing is Bad (Red), Decreasing is Good (Green).
  let trendColor = '';
  if (typeFilter === 'Income') {
      trendColor = isIncreasing ? neonGreen : neonRed; 
  } else {
      trendColor = isIncreasing ? neonRed : neonGreen; 
  }

  const gradientId = "colorTrend";
  const isGreenBadge = trendColor === neonGreen;

  // --- EMPTY STATE (No Historical Data) ---
  if (!loading && (!data || data.error === "No data" || !data.forecast || data.forecast.length === 0)) {
      return (
         <div className="w-full h-full flex flex-col lg:flex-row gap-4 lg:gap-6 animate-in fade-in duration-500 overflow-y-auto lg:overflow-hidden pb-[100px] lg:pb-0">
            <div className="w-full flex-1 bg-white/5 backdrop-blur-sm border border-white/10 rounded-[24px] md:rounded-[32px] flex items-center justify-center min-h-[350px] shrink-0">
                <div className="flex flex-col items-center gap-4 opacity-50">
                    <div className="bg-slate-900/50 p-4 rounded-full border border-white/5 shadow-inner">
                        <LineChart size={32} className={typeFilter === 'Income' ? "text-[#00c48c]" : "text-[#eb3b5a]"} />
                    </div>
                    <p className="text-xs uppercase tracking-widest text-slate-400 font-bold">{typeFilter} Projection</p>
                    <p className="text-[10px] text-slate-500 font-mono tracking-wider">Not enough historical data...</p>
                </div>
            </div>
            {/* Blank Placeholder Card */}
            <div className="w-full lg:w-[350px] flex flex-col gap-4 h-auto shrink-0">
                <div className="bg-gradient-to-br from-slate-900 to-slate-950 border border-white/10 rounded-[24px] md:rounded-[32px] p-6 shadow-2xl relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-4 opacity-[0.03]"><Wallet size={100} className="md:w-[120px] md:h-[120px]"/></div>
                    <p className="text-[10px] text-slate-500 uppercase tracking-[0.2em] font-bold mb-3">Total Projected</p>
                    <h2 className="text-4xl font-mono font-bold text-white tracking-tight mb-2">0,00 <span className="text-lg text-slate-500 ml-1">€</span></h2>
                </div>
            </div>
         </div>
      );
  }

  // --- MAIN RENDER STATE ---
  return (
    <div className="w-full h-full flex flex-col animate-in fade-in duration-700 overflow-y-auto lg:overflow-hidden custom-scrollbar pr-2 lg:pr-4 pb-[100px] lg:pb-0">
      
      <div className="flex flex-col lg:flex-row gap-4 lg:gap-6 h-auto lg:h-full w-full">
        
        {/* Left Column: AI Projection Chart */}
        <div className="w-full flex-1 bg-white/5 backdrop-blur-sm border border-white/10 rounded-[24px] md:rounded-[32px] p-4 md:p-6 shadow-xl relative flex flex-col h-[350px] lg:h-full shrink-0">
          {loading ? (
             <div className="flex-1 flex flex-col items-center justify-center text-slate-500 gap-4">
                <Loader2 className="w-8 h-8 md:w-10 md:h-10 animate-spin text-blue-500" />
                <p className="text-[10px] md:text-xs uppercase tracking-widest animate-pulse">Running AI Projection...</p>
             </div>
          ) : data.error ? (
             <div className="flex-1 flex flex-col items-center justify-center text-[#eb3b5a] gap-4 opacity-80">
                <AlertCircle className="w-10 h-10 md:w-12 md:h-12" />
                <p className="text-xs md:text-sm font-bold text-center px-4">{data.error}</p>
             </div>
          ) : (
            <>
              {/* Chart Header & Trend Indicators */}
              <div className="flex flex-col md:flex-row justify-between items-center mb-4 md:mb-6 shrink-0 gap-4">
                  <h3 className="text-[10px] md:text-xs font-bold text-white uppercase tracking-widest text-center md:text-left">
                      {categoryFilter === 'All' ? 'Trajectory' : `Trajectory • ${categoryFilter}`}
                  </h3>
                  <div className="flex items-center gap-3">
                     <p className="text-[9px] md:text-[10px] text-slate-400 font-mono bg-slate-900/50 px-3 py-1.5 rounded-lg border border-white/10 shadow-inner">
                         {getDateDisplay()}
                     </p>
                     
                     <div className={`flex items-center gap-1.5 text-[9px] font-black px-3 py-1.5 rounded-full bg-slate-900/80 border shadow-lg ${isGreenBadge ? 'text-[#00c48c] border-[#00c48c]/50 drop-shadow-[0_0_8px_rgba(0,196,140,0.6)]' : 'text-[#eb3b5a] border-[#eb3b5a]/50 drop-shadow-[0_0_8px_rgba(235,59,90,0.6)]'}`}>
                        {isIncreasing ? <TrendingUp size={14}/> : <TrendingDown size={14}/>}
                        {isIncreasing ? 'UPTREND' : 'DOWNTREND'}
                    </div>

                  </div>
              </div>

              {/* Recharts Area Chart Container */}
              <div className="flex-1 w-full min-h-[200px]">
                <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={data.forecast} margin={{ top: 5, right: 10, left: -20, bottom: 0 }}>
                    <defs>
                      <linearGradient id={gradientId} x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor={trendColor} stopOpacity={0.4}/>
                        <stop offset="95%" stopColor={trendColor} stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke="#334155" vertical={false} opacity={0.4} />
                    <XAxis dataKey="ds" tick={{ fill: '#64748b', fontSize: 10 }} axisLine={false} tickLine={false} minTickGap={20} tickFormatter={(str) => { const date = new Date(str); return `${date.getDate()}/${date.getMonth() + 1}`; }} />
                    <YAxis tick={{ fill: '#64748b', fontSize: 10 }} axisLine={false} tickLine={false} tickFormatter={(val) => `${val}€`} />
                    <Tooltip contentStyle={{ backgroundColor: '#0f172a', borderColor: '#1e293b', borderRadius: '12px', fontSize: '11px' }} itemStyle={{ color: trendColor }} labelStyle={{ color: '#64748b', marginBottom: '5px' }} formatter={(value) => [`${value.toFixed(2)} €`, 'Predicted']} labelFormatter={(label) => new Date(label).toLocaleDateString()} />
                    <Area type="monotone" dataKey="yhat" stroke={trendColor} strokeWidth={3} fill={`url(#${gradientId})`} />
                  </AreaChart>
                </ResponsiveContainer>
              </div>
            </>
          )}
        </div>

        {/* Right Column: AI Projection Breakdown */}
        {!loading && data && !data.error && (
            <div className="w-full lg:w-[350px] flex flex-col gap-4 h-auto lg:h-full shrink-0">
                {/* Total Future Projection Amount */}
                <div className="bg-gradient-to-br from-slate-900 to-slate-950 border border-white/10 rounded-[24px] md:rounded-[32px] p-6 shadow-2xl relative overflow-hidden shrink-0">
                    <div className="absolute top-0 right-0 p-4 opacity-[0.03]"><Wallet size={100} className="md:w-[120px] md:h-[120px]" /></div>
                    <p className="text-[10px] text-slate-500 uppercase tracking-[0.2em] font-bold mb-3">Total Projected</p>
                    <h2 className="text-4xl font-mono font-bold text-white tracking-tight mb-2">
                        {data.total_predicted?.toLocaleString('el-GR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) || '0,00'}
                        <span className="text-lg text-slate-500 ml-1">€</span>
                    </h2>
                </div>

                {/* Sub-Category AI Prediction Breakdown (Hidden for Income views) */}
                {typeFilter !== 'Income' && (
                    <div className="flex-1 bg-white/[0.02] border border-white/5 rounded-[24px] md:rounded-[32px] p-4 flex flex-col min-h-[300px] lg:min-h-0 overflow-hidden">
                        <p className="text-[10px] text-blue-500 uppercase tracking-[0.2em] font-bold mb-4 px-2 shrink-0">
                            {categoryFilter === 'All' ? 'Breakdown' : 'Details'}
                        </p>
                        <div className="flex-1 flex flex-col gap-2 overflow-y-auto custom-scrollbar pr-1">
                            {data.breakdown && data.breakdown.map((item, index) => (
                                 <div key={item.category} className="flex items-center justify-between p-3 rounded-xl bg-white/[0.03] border border-white/5 hover:bg-white/[0.05] transition-colors group">
                                    <div className="flex items-center gap-3">
                                        <div className="w-1.5 h-8 rounded-full bg-blue-500/50 group-hover:bg-blue-500 transition-colors"></div>
                                        <div>
                                            <p className="text-[11px] font-bold text-white uppercase tracking-tighter">{item.category}</p>
                                        </div>
                                    </div>
                                    <div className="text-right">
                                        <p className="text-sm font-mono font-bold text-white">{item.amount.toLocaleString('el-GR', {maximumFractionDigits: 0})} €</p>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>
        )}
      </div>
    </div>
  );
};

export default Forecasting;